def execute(destination: bytearray, source: bytes) -> None:
    """Write the thirty-six Monolith7 output words into destination[:144].

    Signature matches the retired ``_generated/monolith7.py`` entry point.
    """
    words = struct.unpack("<24I", bytes(source[:96]))
    destination[:144] = struct.pack("<36I", *execute_words(words))
